#!/bin/sh
# Generated by scripts/build-installers.ps1. Do not edit.

set -eu

VERSION="${DRAWPLATE_VERSION:-}"
INSTALL_DIR="${DRAWPLATE_INSTALL_DIR:-}"
REPO="${DRAWPLATE_REPO:-migueljocode/Drawplate}"
BASE_URL="${DRAWPLATE_BASE_URL:-https://github.com/$REPO/releases}"
FROM_ARCHIVE="${DRAWPLATE_FROM_ARCHIVE:-}"
FROM_SHA256="${DRAWPLATE_SHA256:-}"
NO_SETUP="${DRAWPLATE_NO_SETUP:-0}"
YES="${DRAWPLATE_YES:-0}"
UNINSTALL="${DRAWPLATE_UNINSTALL:-0}"

usage() {
    printf '%s\n' "Usage: install.sh [--version <tag>] [--dir <folder>] [--no-setup] [--yes] [--uninstall] [--from <archive> --sha256 <hash>] [--help]"
}

error() {
    printf 'Error: %s\n' "$1" >&2
    printf 'Hint: %s\n' "$2" >&2
    exit "$3"
}

sha256_file() {
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum "$1" | awk '{print $1}'
    elif command -v shasum >/dev/null 2>&1; then
        shasum -a 256 "$1" | awk '{print $1}'
    else
        error "No SHA-256 utility is available." "Install sha256sum or shasum." 13
    fi
}

progress_complete() {
    file=$1
    started=$2
    printf '%s\n' '      25%' '      50%' '      75%'
    bytes=$(wc -c < "$file" | tr -d ' ')
    finished=$(date +%s)
    elapsed=$((finished - started))
    mib=$(awk -v value="$bytes" 'BEGIN { printf "%.1f", value / 1048576 }')
    printf '      100%%  %s MiB in %ss\n' "$mib" "$elapsed"
}

while [ "$#" -gt 0 ]; do
    case "$1" in
        --version)
            [ "$#" -ge 2 ] || error "Missing value for --version." "Provide a release tag." 10
            VERSION=$2
            shift 2
            ;;
        --dir)
            [ "$#" -ge 2 ] || error "Missing value for --dir." "Provide an install folder." 10
            INSTALL_DIR=$2
            shift 2
            ;;
        --no-setup) NO_SETUP=1; shift ;;
        --yes) YES=1; shift ;;
        --uninstall) UNINSTALL=1; shift ;;
        --from)
            [ "$#" -ge 2 ] || error "Missing value for --from." "Provide an archive path." 10
            FROM_ARCHIVE=$2
            shift 2
            ;;
        --sha256)
            [ "$#" -ge 2 ] || error "Missing value for --sha256." "Provide the archive SHA-256." 10
            FROM_SHA256=$2
            shift 2
            ;;
        --help) usage; exit 0 ;;
        *) error "Unknown option: $1" "Run 'install.sh --help'." 10 ;;
    esac
done

if [ -n "$FROM_ARCHIVE" ] && [ -z "$FROM_SHA256" ]; then
    error "--sha256 is required with --from." "Provide the archive SHA-256 hash." 10
fi

UNAME_M=$(uname -m)
OS_NAME=$(uname -s)
case "$OS_NAME:$UNAME_M" in
    Linux:x86_64) RID=linux-x64 ;;
    Linux:aarch64|Linux:arm64) RID=linux-arm64 ;;
    Darwin:arm64) RID=osx-arm64 ;;
    *) error "Unsupported platform: $OS_NAME $UNAME_M." "Supported: linux-x64, linux-arm64, osx-arm64, win-x64." 11 ;;
esac

BIN_DIR="${INSTALL_DIR:-$HOME/.local/bin}"
DATA_DIR="$HOME/.local/share/drawplate"
BINARY="$BIN_DIR/drawplate"
MANIFEST="$DATA_DIR/install.json"

if [ "$UNINSTALL" = "1" ]; then
    printf '%s\n' '[1/4] Locating installation ..... [ok] done' '[2/4] Removing files ............ [ok] done'
    rm -f "$BINARY" "$BINARY.old" "$MANIFEST"
    rmdir "$BIN_DIR" 2>/dev/null || true
    rmdir "$DATA_DIR" 2>/dev/null || true
    printf '%s\n' '[3/4] Updating PATH ............. [ok] done' '[4/4] Finishing ................. [ok] done'
    printf '%s\n' "Removed Drawplate. FFmpeg was not touched."
    exit 0
fi

if [ -z "$VERSION" ]; then
    LOCATION=$(curl -fsSI "$BASE_URL/latest" | awk 'tolower($1) == "location:" { sub(/\r$/, "", $2); print $2; exit }')
    VERSION=${LOCATION##*/}
fi
[ -n "$VERSION" ] || error "Could not find a release for $REPO." "Check your internet connection, or set DRAWPLATE_VERSION." 12
TAG=$VERSION
PKG_VERSION=${TAG#v}
printf 'Drawplate installer %s\n' "$PKG_VERSION"
ARCHIVE="drawplate-$TAG-$RID.tar.gz"
URL="$BASE_URL/download/$TAG/$ARCHIVE"

mkdir -p "$DATA_DIR"
LOCK_DIR="$DATA_DIR/.lock"
if ! mkdir "$LOCK_DIR" 2>/dev/null; then
    if command -v stat >/dev/null 2>&1; then
        LOCK_TIME=$(stat -c %Y "$LOCK_DIR" 2>/dev/null || stat -f %m "$LOCK_DIR" 2>/dev/null || echo 0)
    else
        LOCK_TIME=0
    fi
    NOW=$(date +%s)
    LOCK_AGE=$((NOW - LOCK_TIME))
    if [ "$LOCK_AGE" -lt 1800 ]; then
        error "Another installation is running (lock: $LOCK_DIR)." "Wait for it, or delete that folder if no installer is running." 15
    fi
    rm -rf "$LOCK_DIR"
    mkdir "$LOCK_DIR" || error "Could not create lock $LOCK_DIR." "Choose another install location." 5
fi
STAGING_DIR="$BIN_DIR/.drawplate-staging-$$"
trap 'rm -rf "$LOCK_DIR" "$STAGING_DIR"' EXIT
trap 'rm -rf "$LOCK_DIR" "$STAGING_DIR"; exit 130' HUP INT TERM

REPAIR=0
if [ -f "$MANIFEST" ] && [ -f "$BINARY" ]; then
    MANIFEST_VERSION=$(sed -n 's/.*"version":"\([^"]*\)".*/\1/p' "$MANIFEST")
    MANIFEST_HASH=$(sed -n 's/.*"binarySha256":"\([^"]*\)".*/\1/p' "$MANIFEST")
    BINARY_HASH=$(sha256_file "$BINARY")
    BINARY_VERSION=$("$BINARY" --version 2>/dev/null || true)
    if [ "$MANIFEST_VERSION" = "$PKG_VERSION" ] && [ "$BINARY_HASH" = "$MANIFEST_HASH" ] && [ "$BINARY_VERSION" = "drawplate $PKG_VERSION" ]; then
        printf '%s\n' '[1/8] Detecting platform ..... [ok]' "[2/8] Finding release ........ [ok] $TAG" '[3/8] Downloading Drawplate .... [skipped] up to date' '[4/8] Downloading checksums .... [skipped] up to date' '[5/8] Verifying checksum ....... [skipped] up to date' '[6/8] Installing ............. [skipped] up to date' '[7/8] Checking the install .... [skipped] up to date' '[8/8] Finishing .............. [ok] done'
        printf '\nInstalled Drawplate %s to %s\n' "$PKG_VERSION" "$BINARY"
        printf '%s\n' 'Next:' '  drawplate --help' '  drawplate setup        (shows how to install FFmpeg)'
        case ":$PATH:" in *":$BIN_DIR:"*) ;; *) printf 'Note: %s is not on your PATH.\n' "$BIN_DIR" ;; esac
        exit 0
    fi
    REPAIR=1
fi

mkdir -p "$STAGING_DIR" "$BIN_DIR"
printf '%s\n' "[1/8] Detecting platform ..... [ok] $RID" "[2/8] Finding release ........ [ok] $TAG"
printf '%s\n' '[3/8] Downloading Drawplate ....'
DOWNLOAD_START=$(date +%s)
if [ -n "$FROM_ARCHIVE" ]; then
    cp "$FROM_ARCHIVE" "$STAGING_DIR/$ARCHIVE" || error "Download failed: $FROM_ARCHIVE." "Check the offline archive path." 12
else
    curl -fsSL -o "$STAGING_DIR/$ARCHIVE" "$URL" || error "Download failed: $URL." "Retry, or use --from <archive> --sha256 <hash>." 12
fi
progress_complete "$STAGING_DIR/$ARCHIVE" "$DOWNLOAD_START"

ACTUAL_HASH=$(sha256_file "$STAGING_DIR/$ARCHIVE")
if [ -n "$FROM_ARCHIVE" ]; then
    EXPECTED_HASH=$FROM_SHA256
else
    SUMS_URL="$BASE_URL/download/$TAG/SHA256SUMS"
    SUMS_START=$(date +%s)
    curl -fsSL -o "$STAGING_DIR/SHA256SUMS" "$SUMS_URL" || error "Download failed: $SUMS_URL." "Retry." 12
    progress_complete "$STAGING_DIR/SHA256SUMS" "$SUMS_START"
    EXPECTED_HASH=$(awk -v name="$ARCHIVE" '{ file = $2; sub(/^\.\//, "", file) } file == name { print $1; exit }' "$STAGING_DIR/SHA256SUMS")
fi
if [ -z "$EXPECTED_HASH" ] || [ "$EXPECTED_HASH" != "$ACTUAL_HASH" ]; then
    error "Checksum mismatch for $ARCHIVE." "Nothing was installed. Retry; if it repeats, report it." 13
fi
printf '%s\n' '[4/8] Downloading checksums .... [ok] done' '[5/8] Verifying checksum ....... [ok] done'

mkdir -p "$STAGING_DIR/x"
tar -xzf "$STAGING_DIR/$ARCHIVE" -C "$STAGING_DIR/x" || error "Could not install to $BIN_DIR." "The release archive could not be extracted." 14
FILE_COUNT=$(find "$STAGING_DIR/x" -type f | wc -l | tr -d ' ')
if [ "$FILE_COUNT" -ne 3 ] || [ ! -f "$STAGING_DIR/x/drawplate" ] || [ ! -f "$STAGING_DIR/x/LICENSE" ] || [ ! -f "$STAGING_DIR/x/THIRD-PARTY-NOTICES.md" ]; then
    error "Could not install to $BIN_DIR." "The archive contains unexpected files." 14
fi

if [ -f "$BINARY" ]; then
    mv "$BINARY" "$BINARY.old"
fi
chmod +x "$STAGING_DIR/x/drawplate"
mv "$STAGING_DIR/x/drawplate" "$BINARY"
BINARY_VERSION=$("$BINARY" --version 2>/dev/null || true)
if [ "$BINARY_VERSION" != "drawplate $PKG_VERSION" ]; then
    rm -f "$BINARY"
    if [ -f "$BINARY.old" ]; then mv "$BINARY.old" "$BINARY"; fi
    error "The installed program did not start or reported the wrong version. The previous version was restored." "Retry with a verified release archive." 14
fi
rm -f "$BINARY.old"

INSTALLED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)
BINARY_HASH=$(sha256_file "$BINARY")
ARCHIVE_HASH=$(sha256_file "$STAGING_DIR/$ARCHIVE")
MANIFEST_TMP="$MANIFEST.tmp.$$"
printf '{"version":"%s","rid":"%s","archiveSha256":"%s","binarySha256":"%s","installedAt":"%s","path":"%s"}\n' "$PKG_VERSION" "$RID" "$ARCHIVE_HASH" "$BINARY_HASH" "$INSTALLED_AT" "$BINARY" > "$MANIFEST_TMP"
mv -f "$MANIFEST_TMP" "$MANIFEST"

if [ "$REPAIR" -eq 1 ]; then
    printf '%s\n' '[6/8] Installing ............. [ok] repairing'
else
    printf '%s\n' '[6/8] Installing ............. [ok] done'
fi
printf '%s\n' '[7/8] Checking the install .... [ok] done' '[8/8] Finishing .............. [ok] done'
printf '\nInstalled Drawplate %s to %s\n' "$PKG_VERSION" "$BINARY"
printf '%s\n' 'Next:' '  drawplate --help' '  drawplate setup        (shows how to install FFmpeg)'
case ":$PATH:" in *":$BIN_DIR:"*) ;; *) printf 'Note: %s is not on your PATH.\n' "$BIN_DIR" ;; esac

if ! command -v ffmpeg >/dev/null 2>&1 && [ "$NO_SETUP" = "0" ] && [ "$YES" = "0" ]; then
    printf '%s\n' 'FFmpeg was not found on this machine.'
    if [ -t 0 ] && [ -t 1 ]; then
        printf "Run 'drawplate setup' now? [Y/n] "
        read -r answer || answer=y
        case "$answer" in n|N) ;; *) "$BINARY" setup || true ;; esac
    fi
elif [ "$YES" = "1" ]; then
    "$BINARY" setup || true
fi

exit 0
